--region public
function MidFestivalBtnLetterBehavior:Refresh()
    self:InitData()
    self:RefreshUI()
end

function MidFestivalBtnLetterBehavior:OnClick()
    if not self._activityMidFestivalComponent:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    local moduleId = ActivityMidFestivalMgr:GetMidFestivalMainDialogId()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    UIModule.OpenDialog({
        id = info.moduleId
    }, {
        { id = moduleId }
    })
end
--endregion public

--region private
function MidFestivalBtnLetterBehavior:InitData()
    self._isActive = self._activityMidFestivalComponent:IsActive()
    ---@type ActivityMidFestivalComponent
    self._activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    self._homeDojo = self._activityComp:GetHomeDojo()
    
    local info = self._homeDojo.entranceConf[self.config.index]
    self.config.id = info.id
    local lockLevel = info.unlockLevel
    self._isUnLock = checkBool(checkNumber(self._homeDojo.mainQuestId) >= checkNumber(lockLevel))
    self.config.vo = ActivityMidFestivalMgr:LoadMainEntryVoById(self.config.id)
    ActivityMidFestivalMgr:UpdateLetterRedPoint()
end

function MidFestivalBtnLetterBehavior:RefreshUI()
    if not self._isActive or not self._isUnLock then
        CfUtils.FillText(self.Lock.transform:Find("Text").gameObject, localize("未解锁"))
        CfUtils.SetActive(self.Lock, true)
        if not string.isEmpty(self.config.vo.unlockPicture) then
            CfUtils.FillImage(self.ImgLetter, self.config.vo.unlockPicture)
        end
        local allChildGrayGraphics = self.controller.gameObject:EnsureComponent(typeof(UIAllChildGrayGraphics))
        if allChildGrayGraphics then
            allChildGrayGraphics:MarkGray(true)
        end
    else
        if not string.isEmpty(self.config.vo.name) then
            CfUtils.FillText(self.TabNode.transform:Find("Text").gameObject, self.config.vo.name)
        end
    end
    CfUtils.SetActive(self.Lock, not self._isActive)
    local hasRedPoint = CfUtils.GetLocalData("MidFestivalLetterRedPoint", "false") == "true"
    CfUtils.SetActive(self.TabNode.transform:Find("ImgNew"), hasRedPoint)
end
--endregion private

